// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';
import { ndarray } from '@stdlib/types/ndarray';

/**
* Chart data.
*/
type Data = Collection | ndarray;

/**
* Interface describing constructor options.
*/
interface Options {
	/**
	* Symbol colors.
	*/
	colors?: string | Array<string>;

	/**
	* Symbol edge colors.
	*/
	edgeColors?: string | Array<string>;

	/**
	* Symbol edge opacity.
	*/
	edgeOpacity?: number | Array<number>;

	/**
	* Symbol edge width(s) (in pixels).
	*/
	edgeWidth?: number | Array<number>;

	/**
	* Boolean indicating whether to display a chart legend.
	*/
	legend?: boolean;

	/**
	* Symbol(s).
	*/
	symbols?: string | Array<string>;

	/**
	* Symbol opacity.
	*/
	symbolOpacity?: number | Array<number>;

	/**
	* Symbol size(s) in pixels squared.
	*/
	symbolSize?: number | Array<number>;
}

/**
* Scatterplot.
*/
declare class Scatterplot {
	/**
	* Scatterplot constructor.
	*
	* @param options - constructor options
	* @returns scatterplot instance
	*
	* @example
	* var chart = new Scatterplot();
	* // returns <Scatterplot>
	*/
	constructor( options?: Options );

	/**
	* Scatterplot constructor.
	*
	* @param y - y-values
	* @param options - constructor options
	* @returns scatterplot instance
	*
	* @example
	* var chart = new Scatterplot( [ 4, 5, 6 ] );
	* // returns <Scatterplot>
	*/
	constructor( y: Data | Array<Data>, options?: Options );

	/**
	* Scatterplot constructor.
	*
	* @param x - x-values
	* @param y - y-values
	* @param options - constructor options
	* @returns scatterplot instance
	*
	* @example
	* var chart = new Scatterplot( [ 1, 2, 3 ], [ 4, 5, 6 ] );
	* // returns <Scatterplot>
	*/
	constructor( x: Data | Array<Data>, y: Data | Array<Data>, options?: Options );

	/**
	* Serializes a chart to a JSON object.
	*
	* @returns JSON object
	*
	* @example
	* var chart = new Scatterplot( [ 1, 2, 3 ], [ 4, 5, 6 ] );
	*
	* var v = chart.toJSON();
	* // returns {...}
	*/
	toJSON(): Record<string, unknown>;
}


// EXPORTS //

export = Scatterplot;
